/* From Uiverse.io by andrew-demchenk0 - Tags: form */
/* you can choose any color you want. don't be afraid to experiment  */

.__UIV_SCOPE__ .input, .__UIV_SCOPE__ button {
  width: 100%;
  height: 40px;
  position: relative;
  padding: 10px;
  border: 0.1px solid #575cb5;
}

.__UIV_SCOPE__ button {
  background: #6d74e3;
  border: none;
}

.__UIV_SCOPE__ .wrapper {
  position: relative;
  transform: skewY(-14deg);
}

.__UIV_SCOPE__ .wrapper li, .__UIV_SCOPE__ button {
  position: relative;
  list-style: none;
  width: 200px;
  z-index: var(--i);
  transition: 0.3s;
  color: white;
}

.__UIV_SCOPE__ .wrapper li::before, .__UIV_SCOPE__ button::before {
  position: absolute;
  content: '';
  background: #6d74e3;
  top: 0;
  left: -40px;
  width: 40px;
  height: 40px;
  transform-origin: right;
  transform: skewY(45deg);
  transition: 0.3s;
}

.__UIV_SCOPE__ .wrapper li::after, .__UIV_SCOPE__ button::after {
  position: absolute;
  content: '';
  background: #6d74e3;
  width: 200px;
  height: 40px;
  top: -40px;
  left: 0;
  transform-origin: bottom;
  transform: skewX(45deg);
  transition: 0.3s;
}

.__UIV_SCOPE__ .wrapper li:nth-child(1)::after, .__UIV_SCOPE__ .wrapper li:nth-child(1)::before {
  background-color: #d8daf7;
}

.__UIV_SCOPE__ .wrapper li:nth-child(2)::after, .__UIV_SCOPE__ .wrapper li:nth-child(2)::before {
  background-color: #c2c5f3;
}

.__UIV_SCOPE__ .wrapper li:nth-child(3)::after, .__UIV_SCOPE__ .wrapper li:nth-child(3)::before {
  background-color: #989deb;
}

.__UIV_SCOPE__ li .input {
  outline: none;
  border: none;
  color: black;
}

.__UIV_SCOPE__ li .input::placeholder {
  color: black;
}

.__UIV_SCOPE__ li:nth-child(1) .input {
  background: #d8daf7;
}

.__UIV_SCOPE__ li:nth-child(2) .input {
  background: #c2c5f3;
}

.__UIV_SCOPE__ li:nth-child(3) .input {
  background: #989deb;
}


.__UIV_SCOPE__ li:nth-child(1) .input:focus {
  outline: none;
  border: 3.5px solid #d8daf7;
}

.__UIV_SCOPE__ li:nth-child(2) .input:focus {
  outline: none;
  border: 3.5px solid #c2c5f3;
}

.__UIV_SCOPE__ li:nth-child(3) .input:focus {
  outline: none;
  border: 3.5px solid #989deb;
}

.__UIV_SCOPE__ .wrapper li:hover, .__UIV_SCOPE__ button:hover {
  transform: translateX(-20px);
}

.__UIV_SCOPE__ button:hover, .__UIV_SCOPE__ button:hover::before, .__UIV_SCOPE__ button:hover::after {
  background: #575cb5;
}

.__UIV_SCOPE__ button:active {
  transform: translateX(0px);
}
